import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../../themes/stack_colors.dart';
import '../../../utilities/text_styles.dart';
import '../../../utilities/util.dart';
import '../../../wallets/crypto_currency/crypto_currency.dart';
import '../../../widgets/animated_widgets/rotating_arrows.dart';
import '../../../widgets/desktop/secondary_button.dart';
import '../../../widgets/stack_dialog.dart';
import '../../../widgets/tx_send_animation.dart';

class BuildingTransactionDialog extends ConsumerStatefulWidget {
  const BuildingTransactionDialog({
    super.key,
    required this.onCancel,
    required this.coin,
  });

  final VoidCallback onCancel;
  final CryptoCurrency coin;

  @override
  ConsumerState<BuildingTransactionDialog> createState() =>
      _BuildingTransactionDialogState();
}

class _BuildingTransactionDialogState
    extends ConsumerState<BuildingTransactionDialog> {
  late final VoidCallback onCancel;

  @override
  void initState() {
    onCancel = widget.onCancel;

    super.initState();
  }

  @override
  Widget build(BuildContext context) {
    if (Util.isDesktop) {
      return Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const TxSendAnimation(width: 420),
          const SizedBox(height: 24),
          Text("Generating transaction", style: STextStyles.desktopH3(context)),
          const SizedBox(height: 24),
          const RotatingArrows(width: 40, height: 40),
          const SizedBox(height: 32),
          SecondaryButton(
            buttonHeight: ButtonHeight.l,
            label: "Cancel",
            onPressed: () {
              onCancel.call();
            },
          ),
        ],
      );
    } else {
      return WillPopScope(
        onWillPop: () async {
          return false;
        },
        child: StackDialog(
          header: const TxSendAnimation(),
          title: "Generating transaction",
          icon: const RotatingArrows(width: 24, height: 24),
          rightButton: TextButton(
            style: Theme.of(context)
                .extension<StackColors>()!
                .getSecondaryEnabledButtonStyle(context),
            child: Text("Cancel", style: STextStyles.itemSubtitle12(context)),
            onPressed: () {
              Navigator.of(context).pop();
              onCancel.call();
            },
          ),
        ),
      );
    }
  }
}
